import React, { useState } from 'react';
import type { ReactNode } from 'react';
import { SortableContainer, SortableElement, SortableHandle } from 'react-sortable-hoc';
import { IconDragDotVertical } from '@arco-design/web-react/icon';
import CConditions from '..';
import { MyCondition, newCondition } from './basic'; // 代码参见「基本用法」部分
import type { Condition } from './basic';

const CConditionsGroup = CConditions.Group;

interface ValType {
  relation: string;
  groups: {
    relation: string;
    conditions: Condition[];
  }[];
}

const DragHandle = SortableHandle(() => <IconDragDotVertical style={{ cursor: 'move', color: '#555' }} />);
const SortableItem = SortableElement(({ children }: { children: ReactNode }) => (
  <div>
    <DragHandle />
    {children}
  </div>
));
const SortableList = SortableContainer(({ children }: { children: ReactNode }) => <div>{children}</div>);

const ConditionWrapper = (props: any) => <SortableItem {...props} />;

const Container = (props: {
  children: ReactNode;
  className: string;
  value?: ValType['groups'][number];
  onChange?: (value: ValType['groups'][number]) => void;
}) => {
  const { value, onChange, ...rest } = props;
  const onSortEndHandler = ({ oldIndex, newIndex }: { oldIndex: number; newIndex: number }) => {
    if (oldIndex !== newIndex) {
      const conditions = [...(value?.conditions || [])];
      const item = conditions.splice(oldIndex, 1)[0];
      conditions.splice(newIndex, 0, item);
      onChange?.({ ...value, conditions } as ValType['groups'][number]);
    }
  };
  return <SortableList onSortEnd={onSortEndHandler} useDragHandle {...rest} />;
};

export default () => {
  const [value, setValue] = useState<ValType>({
    relation: 'and',
    groups: [
      {
        relation: 'or',
        conditions: [{ field: 'name', operator: 'eq', value: 'tod' }, newCondition()],
      },
    ],
  });

  return (
    <CConditionsGroup
      groupRender={(value, onChange, index) => {
        return (
          <CConditions
            value={value}
            onChange={onChange}
            allowClear={false}
            newCondition={newCondition}
            conditionRender={(val, onChangeCondition) => <MyCondition value={val} onChange={onChangeCondition} />}
            Container={Container}
            ConditionWrapper={ConditionWrapper}
            key={index}
          />
        );
      }}
      conditionRender={() => null}
      value={value as ValType}
      onChange={value => {
        setValue(value);
      }}
    />
  );
};

