import React, { useEffect, useRef, useState } from 'react';
import { Input, Select, Switch } from '@arco-design/web-react';
import CConditions from '..';
import { CForm } from '@cloud-materials/common';
import type { CForm as CFormType } from '@cloud-materials/common/es/CForm';

export interface Condition {
  field: string;
  operator: string;
  value: string;
}

export interface ValType {
  relation: string;
  conditions: Condition[];
}

/**
 * 单个条件
 */
export const MyCondition: React.FC<{
  readonly?: boolean;
  disabled?: boolean;
  value?: Condition;
  onChange?: (val: Condition) => void;
}> = ({ readonly = false, disabled, value, onChange }) => {
  if (readonly) {
    return (
      <div style={{ display: 'flex', width: 300, lineHeight: '2em', justifyContent: 'space-between' }}>
        <span>{value?.field}</span>
        <span>{value?.operator}</span>
        <span>{value?.value}</span>
      </div>
    );
  }
  return (
    <div style={{ display: 'inline-flex', margin: '8px 1em 8px 0' }}>
      <Input
        disabled={disabled}
        style={{ width: 200 }}
        placeholder="字段"
        value={value?.field}
        onChange={val => onChange?.({ ...(value as Condition), field: val })}
      />
      <Select
        disabled={disabled}
        style={{ width: 100, margin: '0 1em' }}
        placeholder="运算符"
        options={['eq', 'neq', 'gt', 'gte', 'lt', 'lte']}
        value={value?.operator}
        onChange={(val: string) => onChange?.({ ...(value as Condition), operator: val })}
      />
      <Input
        disabled={disabled}
        style={{ width: 200 }}
        placeholder="值"
        value={value?.value as string}
        onChange={val => onChange?.({ ...(value as Condition), value: val })}
      />
    </div>
  );
};

export const newCondition = () => ({ field: '', operator: undefined, value: '' } as unknown as Condition);

export default () => {
  const [readonly, setReadonly] = useState(false);
  const formRef = useRef<CFormType>();
  useEffect(() => {
    formRef?.current?.setData({ readonly });
  }, [readonly]);

  const config = CForm.defineConfig({
    initConfig: () => {
      return { initialValues: { CConditions: { relation: 'or', conditions: [newCondition()] } } };
    },
    fields: [
      {
        name: 'CConditions',
        componentOptions: CForm.defineComponentOption(CConditions, form => {
          const { readonly } = form.data;
          return {
            conditionRender: (value: Condition, onChange: (val: Condition) => void) => (
              <MyCondition value={value} onChange={onChange} readonly={readonly} />
            ),
            newCondition,
            readonly,
          };
        }),
        decoratorOptions: {
          component: 'FormItem',
        },
      },
    ],
  });

  return (
    <>
      <div style={{ marginBottom: 16 }}>
        <span style={{ marginRight: 16 }}>切换到「展示」态</span>
        <Switch checked={readonly} onChange={setReadonly} />
      </div>
      <CForm ref={formRef} config={config} defaultDecoratorProps={{ isFullPage: false }} />
    </>
  );
};

